const columnDefinitions = { units:[['unitCode','编码'],['unitName','名称'],['unitPath','组织路径',180],['unitType','类型'],['status','状态',90,'status']],meters:[['meterCode','编码'],['meterName','名称'],['energyTypeName','能源类型'],['organizationUnitPath','用能单元',180],['multiplier','倍率',90,'','number'],['status','状态',90,'status']],readings:[['readingDate','抄表日期'],['meterName','计量器具'],['organizationUnitPath','用能单元',170],['normalizedUsageValue','标准化用量',130,'','number'],['energyTrace','能耗追溯',130,'trace'],['recordStatus','状态',90,'status']],generation:[['normalizedMonth','月份'],['organizationUnitPath','用能单元',180],['generationValueKwh','发电量 kWh',130,'','number'],['selfUseValueKwh','自发自用 kWh',130,'','number'],['gridExportValueKwh','上网 kWh',120,'','number'],['selfUseRate','自用 / 上网率',140,'','rates'],['recordStatus','状态',90,'status']],productionUnits:[['unitCode','编码'],['unitName','名称'],['organizationUnitPath','所属用能单元',180],['productName','产品'],['outputUnit','产量单位'],['status','状态',90,'status']],productionOutputs:[['normalizedMonth','月份'],['productionUnitName','产能单元'],['outputValue','产量值',120,'','number'],['outputUnit','单位'],['dataSource','来源'],['recordStatus','状态',90,'status']] }; const columns=computed(() => (columnDefinitions[config.value.key] || []).map(([key,label,width,kind,format]) => ({ key,label,width,kind,format }))); const chartData=computed(()=>{ const data=stats.value||{}; if(config.value.key==='productionUnits') return [{label:'启用',value:numberValue(data.productionUnits?.active),color:'#2a78d6'},{label:'停用',value:numberValue(data.productionUnits?.inactive),color:'#eb6834'}]; if(config.value.key==='productionOutputs') return chartRows((data.productionOutputs?.byMonth||[]).map((row) => ({ ...row, chartLabel: `${row.normalizedMonth || '未标注'} · ${row.outputUnit || '未标注单位'} · ${row.recordStatus || '未知状态'}` })),'chartLabel','outputValue'); return chartRows(data[config.value.chart]||[],config.value.chartLabel,config.value.chartValue); }); const chartTitle=computed(()=>config.value.chartTit