const rules={ unitCode:[{required:true,message:'请填写编码',trigger:'blur'}],unitName:[{required:true,message:'请填写名称',trigger:'blur'}],meterCode:[{required:true,message:'请填写仪表编码',trigger:'blur'}],meterName:[{required:true,message:'请填写仪表名称',trigger:'blur'}],energyTypeId:[{required:true,message:'请选择能源类型',trigger:'change'}],organizationUnitId:[{required:true,message:'请选择用能单元',trigger:'change'}],meterDeviceId:[{required:true,message:'请选择计量器具',trigger:'change'}],originalUnit:[{required:true,message:'请填写单位',trigger:'blur'}],productName:[{required:true,message:'请填写产品名称',trigger:'blur'}],outputUnit:[{required:true,message:'请填写产量单位',trigger:'blur'}],productionUnitId:[{required:true,message:'请选择产能单元',trigger:'change'}]};
const safe=async(task)=>{try{return{ok:true,value:await task()};}catch(e){return{ok:false,error:e};}}; const message=(result,fallback='接口请求失败。')=>result?.error?.message||fallback; const number=(value)=>new Intl.NumberFormat('zh-CN',{maximumFractionDigits:2}).format(numberValue(value)); const percent=(value)=>value===null||value===undefined?'—':`${number(numberValue(value)*100)}%`;
async function dependencies(){const [unitResult,meterResult,energyResult,productionResult]=await Promise.all([safe(()=>ledgerApi.units.list({page:1,pageSize:500})),safe(()=>ledgerApi.meters.list({page:1,pageSize:500})),safe(ledgerApi.energyTypes),safe(()=>ledgerApi.productionUnits.list({page:1,pageSize:500}))]);if(unitResult.ok)units.value=unitResult.value.data||[];if(meterResult.ok)meters.value=meterResult.value.data||[];if(energyResult.ok)energyTypes.value=energyResult.value.data||[];if(productionResult.ok)productionUnits.value=productionResult.value.data||[];}
async function load(){if(!can('view'))return;loading.value=true;const params=buildLedgerFilters(applied.value,{page:page.value,pageSize:pageSize.value});const[list,summary]=await Promise.all([safe(()=>api.value.list(params)),safe(()=>api.value.stats(buildLedgerFilters(applied.value)))]);loading.value=false;if(list.ok){rows.value=list.value.data||[];pagination.value=list.value.meta?.pagination||{};listError.value='';}else{rows.value=[];listError.value=message(list);}if(summary.ok){stats.value=summary.value.data||{};statsError.value='';}else{statsError.value=message(summary);}}
function applyFilters(){applied.value={...draft.value};page.value=1;load();}function resetFilters(){draft.value={};applied.value={};page.value=1;load();}function changeSize(){page.value=1;load();}function openCreate(){editing.value=null;form.value=blankForm(config.value.key);formError.value='';drawer.value=true;}function openEdit(row){editing.value=row;form.value={...blankForm(config.value.key),...row};formError.value='';drawer.value=true;}
function createPayload(){const payload={...form.value};if(config.value.key==='generation')payload.energyTypeCode='photovoltaic';if(config.value.key==='readings'){const selected=meters.value.find((item)=>Number(item.id)===Number(payload.meterDeviceId));if(selected){payload.organizationUnitId=selected.organizationUnitId;payload.multiplier=payload.multiplier||selected.multiplier;if(!payload.originalUnit && selected.energyTypeCode==='photovoltaic') payload.originalUnit='kWh';}}return payload;}
async function save(){if(formBlocked.value)return;const valid=await formRef.value?.validate().catch(()=>false);if(!valid)return;saving.value=true;formError.value='';const payload=createPayload();const result=await safe(()=>editing.value?api.value.update(editing.value.id,payload):api.value.create(payload));saving.value=false;if(!result.ok){formError.value=message(result);return;}drawer.value=false;ElMessage.success(editing.value?'已更新。':'已新增。');await load();await dependencies();}
async function confirmDeactivate(row){const isRecord=config.value.record;const reactivating=!isRecord&&row[config.value.statusField]==='inactive';const verb=isRecord?'作废':(reactivating?'启用':'停用');const impact=isRecord?'不会物理删除，历史记录和审计追溯将保留。':(reactivating?'启用后可重新作为 active 台账关联。':'不会物理删除，历史引用继续保留可追溯。');try{await ElMessageBox.confirm(`确认${verb}“${row.unitName||row.meterName||row.productionUnitName||row.organizationUnitName||row.id}”？${impact}`,`确认${verb}`,{type:reactivating?'info':'warning',confirmButtonText:`确认${verb}`,cancelButtonText:'取消'});}catch{return;}const result=await safe(()=>isRecord?api.value.void(row.id):(reactivating?api.value.update(row.id,{...row,status:'active'}):api.value.deactivate(row.id)));if(!result.ok){ElMessage.error(`${verb}失败：${message(result)}`);return;}ElMessage.success(`已${verb}。`);await load();await dependencies();}
