async function runImport(){if(!file.value)return;importLoading.value=true;importError.value='';const result=await safe(()=>config.value.previewImport?api.value.previewImport(file.value):api.value.import(file.value));importLoading.value=false;if(!result.ok){importError.value=message(result);return;}importResult.value=result.value.data||{};if(!config.value.previewImport){ElMessage.success('导入请求已完成，请查看批次结果。');await load();await dependencies();}}
function openExecute(){confirmText.value='';executeError.value='';executeDrawer.value=true;}async function execute(){const preview=activePreview.value;if(!preview||confirmText.value!==preview.confirmText)return;executeLoading.value=true;executeError.value='';const isReading=config.value.key==='readings';const result=await safe(()=>isReading?api.value.generationExecute(buildControlledExecutePayload(preview,'reading-generation')):api.value.executeImport(buildControlledExecutePayload(preview,config.value.key==='generation'?'generation':'production')));executeLoading.value=false;if(!result.ok){executeError.value=message(result);return;}executeDrawer.value=false;importDrawer.value=false;generationPreview.value=null;importResult.value=result.value.data||{};ElMessage.success('受控执行完成，已保留后端审计与备份结果。');await load();await dependencies();}
