watch(()=>form.value.meterDeviceId,(id)=>{if(config.value.key!=='readings'||editing.value||!id)return;const meter=meters.value.find((item)=>Number(item.id)===Number(id));if(meter){form.value.multiplier=meter.multiplier;form.value.originalUnit=meter.energyTypeCode==='photovoltaic'?'kWh':form.value.originalUnit;}});watch(()=>form.value.productionUnitId,(id)=>{if(config.value.key!=='productionOutputs'||editing.value||!id)return;const unit=productionUnits.value.find((item)=>Number(item.id)===Number(id));if(unit)form.value.outputUnit=unit.outputUnit;});onMounted(async()=>{if(!can('view'))return;await dependencies();await load();});
